    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def backtrack(r, c, path):
        if (r, c) == goal:
            return path + [(r, c)]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                result = backtrack(nr, nc, path + [(r, c)])
                if result:
                    return result
        return None

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []
    if start == goal:
        return [start]
    return backtrack(start[0], start[1], [])
