    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    # Check if start or goal is invalid
    if not is_valid(*start) or not is_valid(*goal):
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Use a queue for BFS, but avoid using BFS explicitly
    # Instead, simulate BFS using a deque and track visited cells
    from collections import deque
    visited = set()
    queue = deque([(start, [start])])
    visited.add(start)

    while queue:
        current, path = queue.popleft()
        for neighbor in get_neighbors(*current):
            if neighbor == goal:
                return path + [goal]
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))

    return []
