def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if not (0 <= start_row < rows and 0 <= start_col < cols):
        return []
    if not (0 <= goal_row < rows and 0 <= goal_col < cols):
        return []
    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []
    if start == goal:
        return [start]

    visited = set()
    parent = {}

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited

    from collections import deque

    queue = deque([(start_row, start_col)])
    visited.add((start_row, start_col))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                visited.add((nr, nc))
                parent[(nr, nc)] = (r, c)
                queue.append((nr, nc))
                if (nr, nc) == (goal_row, goal_col):
                    path = []
                    current = (nr, nc)
                    while current in parent:
                        path.append(current)
                        current = parent[current]
                    path.append(start)
                    path.reverse()
                    return path

    return []
