def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    visited = [[False for _ in range(cols)] for _ in range(rows)]
    path = []
    parent = {}

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and not visited[r][c]

    def backtrack(r, c):
        if r == start[0] and c == start[1]:
            path.append((r, c))
            return True
        if (r, c) in parent:
            pr, pc = parent[(r, c)]
            path.append((r, c))
            if backtrack(pr, pc):
                return True
        return False

    from collections import deque

    q = deque()
    q.append(start)
    visited[start[0]][start[1]] = True

    while q:
        r, c = q.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc):
                visited[nr][nc] = True
                parent[(nr, nc)] = (r, c)
                q.append((nr, nc))
                if (nr, nc) == goal:
                    backtrack(nr, nc)
                    return path[::-1]

    return []
