def solve(grid, start, goal):
    if start == goal:
        return [start]
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    visited = set()
    path = {}
    queue = [(start_row, start_col)]

    while queue:
        r, c = queue.pop(0)
        if (r, c) == (goal_row, goal_col):
            break
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] != '#' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    path[(nr, nc)] = (r, c)
                    queue.append((nr, nc))

    if (goal_row, goal_col) not in path:
        return []

    # Reconstruct path
    path_list = [goal]
    while path_list[-1] != start:
        path_list.append(path[path_list[-1]])
    path_list.reverse()
    return path_list
